export function getWnrPagePosition(pdfPageNum: number): { dayNumber: number; subPage: number; totalPages: number } {
  const day = getWnrDayForPdfPage(pdfPageNum);
  let p = Math.max(1, pdfPageNum - 10);
  while (p < pdfPageNum && getWnrDayForPdfPage(p) !== day) {
    p++;
  }
  const dayFirstPage = p;
  const subPage = pdfPageNum - dayFirstPage + 1;

  let endP = pdfPageNum;
  while (endP <= 1172 && getWnrDayForPdfPage(endP) === day) {
    endP++;
  }
  const totalPages = Math.max(1, endP - dayFirstPage);
  return { dayNumber: day, subPage, totalPages };
}
